// Register is the resolver for the register field.
func (r *mutationResolver) Register(ctx context.Context, email string, password string) (*model.AuthPayload, error) {
	addr, err := auth.NormalizeEmail(email)
	if err != nil {
		return nil, apperr.New("adresse email invalide")
	}
	if err := auth.ValidatePassword(password); err != nil {
		return nil, apperr.New("%s", err.Error())
	}
	hash, err := auth.HashPassword(password)
	if err != nil {
		return nil, err
	}
	u, err := r.Users.Create(ctx, addr, hash)
	if errors.Is(err, users.ErrEmailTaken) {
		return nil, apperr.New("%s", err.Error())
	}
	if err != nil {
		return nil, err
	}
	return r.authPayload(u)
}

// Login is the resolver for the login field.
func (r *mutationResolver) Login(ctx context.Context, email string, password string) (*model.AuthPayload, error) {
	invalid := apperr.New("%s", auth.ErrInvalidCredentials.Error())
	addr, err := auth.NormalizeEmail(email)
	if err != nil {
		_ = auth.CheckPassword("", password) // même temps de réponse que pour un vrai compte
		return nil, invalid
	}
	u, err := r.Users.ByEmail(ctx, addr)
	if errors.Is(err, users.ErrNotFound) {
		_ = auth.CheckPassword("", password)
		return nil, invalid
	}
	if err != nil {
		return nil, err
	}
	if auth.CheckPassword(u.PasswordHash, password) != nil {
		return nil, invalid
	}
	return r.authPayload(u)
}

