// CreateAlert is the resolver for the createAlert field.
func (r *mutationResolver) CreateAlert(ctx context.Context, input model.AlertInput) (*model.Alert, error) {
	userID, err := loggedIn(ctx)
	if err != nil {
		return nil, err
	}
	oid, err := bson.ObjectIDFromHex(userID)
	if err != nil {
		return nil, apperr.New("%s", auth.ErrNotLoggedIn.Error())
	}
	if err := r.ensureStation(ctx, input.StationID); err != nil {
		return nil, err
	}

	a := alerts.Alert{UserID: oid, StationID: input.StationID, Fuel: string(input.Fuel), Type: alertTypes[input.Type]}
	if input.Type == model.AlertTypeThreshold {
		if input.Threshold == nil || *input.Threshold < 0.3 || *input.Threshold > 5 {
			return nil, apperr.New("le seuil doit être un prix entre 0,30 € et 5 €")
		}
		a.Threshold = input.Threshold
	}
	created, err := r.AlertRepo.Create(ctx, a)
	if errors.Is(err, alerts.ErrTooManyAlert) {
		return nil, apperr.New("%s", err.Error())
	}
	if err != nil {
		return nil, err
	}
	stations, err := r.Stations.ByIDs(ctx, []string{created.StationID})
	if err != nil {
		return nil, err
	}
	return toAlert(*created, stations), nil
}

