// DeleteAccount is the resolver for the deleteAccount field.
func (r *mutationResolver) DeleteAccount(ctx context.Context, password string) (bool, error) {
	userID, err := loggedIn(ctx)
	if err != nil {
		return false, err
	}
	u, err := r.Users.ByID(ctx, userID)
	if err != nil {
		return false, apperr.New("%s", users.ErrNotFound.Error())
	}
	// Le mot de passe est redemandé : un jeton volé ne suffit pas à supprimer le compte
	if auth.CheckPassword(u.PasswordHash, password) != nil {
		return false, apperr.New("mot de passe incorrect")
	}
	if err := r.AlertRepo.DeleteByUser(ctx, u.ID); err != nil {
		return false, err
	}
	if err := r.Users.Delete(ctx, userID); err != nil {
		return false, err
	}
	return true, nil
}

